from datetime import date

from threetears.evals import Eval

from proration import prorate

def invoice(case):
    """The credit and charge lines for the plan change."""
    lines = prorate(case["old_plan"], case["new_plan"], case["anchor_day"], date.fromisoformat(case["changed_on"]))
    return {"credit": lines.credit_pence, "charge": lines.charge_pence}


def matches_provider(case, out):
    """The invoice lines are the provider's."""
    return (out["credit"], out["charge"]) == (case["credit_pence"], case["charge_pence"])

invoices = Eval("data/invoices.jsonl", runner=invoice, grader=[matches_provider], k=1)
